export async function checkoutCart(items: any[], userId: string, paymentData: any) {
  try {
    // Fetch course details to get validity_days
    const courseIds = items.filter(i => i.type === 'course').map(i => i.id);
    const { data: coursesData } = await supabase
      .from('courses')
      .select('id, validity_days')
      .in('id', courseIds);

    // Insert all purchases
    const purchases = items.map(item => {
      let expires_at = null;
      if (item.type === 'course') {
        const course = coursesData?.find(c => c.id === item.id);
        const validity_days = course?.validity_days || 365;
        expires_at = new Date(Date.now() + validity_days * 24 * 60 * 60 * 1000).toISOString();
      }

      let amount_paid = item.price;
      if (paymentData.total_paid !== undefined && paymentData.cart_total !== undefined && paymentData.cart_total > 0) {
        amount_paid = Math.round(item.price * (paymentData.total_paid / paymentData.cart_total));
      }

      return {
        student_id: userId,
        course_id: item.id,
        status: 'completed',
        razorpay_order_id: paymentData.razorpay_order_id,
        razorpay_payment_id: paymentData.razorpay_payment_id,
        expires_at,
        amount_paid,
        coupon_code: paymentData.coupon_code || null,
        receipt_id: `RCPT-${Math.random().toString(36).substring(2, 8).toUpperCase()}`
      };
    });

    const { error: purchaseError } = await supabase.from('purchases').insert(purchases);
    if (purchaseError) throw new Error(purchaseError.message);

    // Enroll in live batches if applicable
    for (const item of items) {
      if (item.type === 'course' && item.is_live) {
        const { data: course } = await supabase.from('courses').select('batch_id').eq('id', item.id).single();
        if (course && course.batch_id) {
          await supabase.from('batch_students').insert([
            { batch_id: course.batch_id, student_id: userId }
          ]);
        }
      }
    }

    revalidatePath('/store');
    revalidatePath('/student');
    return { success: true };
  } catch (error: any) {
    console.error("Checkout Cart Error:", error);
    return { success: false, error: error.message };
  }
}

"use server";

import { createClient } from "@supabase/supabase-js";

// Initialize Supabase Client internally for Server Actions
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://placeholder-url.supabase.co";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || "placeholder-key";

// Use a service key if available to bypass RLS for admin actions, or anon key if not (assuming RLS is configured appropriately)
const supabase = createClient(supabaseUrl, supabaseServiceKey);

export async function createLiveClass(payload: any) {
  // Extract courseIds if it's an array, otherwise fallback to single course_id
  const { course_id, course_ids, ...rest } = payload;
  const ids = course_ids && Array.isArray(course_ids) && course_ids.length > 0 
    ? course_ids 
    : (course_id ? [course_id] : []);

  if (ids.length === 0) throw new Error("No course selected.");

  // Map to multiple rows
  const finalRows = ids.map((cId: string) => ({
    ...rest,
    course_id: cId,
    topic: rest.title || 'Untitled',
    start_time: rest.scheduled_time || new Date().toISOString(),
    meeting_link: rest.youtube_video_id || ''
  }));

  const { data, error } = await supabase
    .from('live_classes')
    .insert(finalRows)
    .select();

  if (error) throw new Error(error.message);
  return data;
}

export async function updateLiveClassGroup(oldYoutubeVideoId: string, payload: any) {
  const { course_id, course_ids, ...rest } = payload;

  const { data: existingClasses } = await supabase
    .from('live_classes')
    .select('id, course_id')
    .eq('meeting_link', oldYoutubeVideoId);

  const existingCourseIds = existingClasses ? existingClasses.map((c: any) => c.course_id) : [];

  const ids = course_ids && Array.isArray(course_ids) && course_ids.length > 0 
    ? course_ids 
    : (course_id ? [course_id] : []);

  if (ids.length === 0) throw new Error("No course selected.");

  const toAdd = ids.filter((id: string) => !existingCourseIds.includes(id));
  const toDelete = existingCourseIds.filter((id: string) => !ids.includes(id));
  const toUpdate = ids.filter((id: string) => existingCourseIds.includes(id));

  // Common fields to update/insert
  const commonData = {
    ...rest,
    topic: rest.title || 'Untitled',
    start_time: rest.scheduled_time || new Date().toISOString(),
    meeting_link: rest.youtube_video_id || ''
  };

  // Perform updates
  if (toUpdate.length > 0) {
    const updatePromises = toUpdate.map((cId: string) => 
      supabase.from('live_classes').update(commonData)
        .eq('meeting_link', oldYoutubeVideoId)
        .eq('course_id', cId)
    );
    await Promise.all(updatePromises);
  }

  // Perform deletes
  if (toDelete.length > 0) {
    const classIdsToDelete = existingClasses
      ?.filter((c: any) => toDelete.includes(c.course_id))
      .map((c: any) => c.id) || [];

    if (classIdsToDelete.length > 0) {
      await supabase.from('live_classes').delete().in('id', classIdsToDelete);
    }
  }

  // Perform inserts
  if (toAdd.length > 0) {
    const insertRows = toAdd.map((cId: string) => ({
      ...commonData,
      course_id: cId
    }));
    await supabase.from('live_classes').insert(insertRows);
  }

  return true;
}

