"use client";

import { useState, useEffect, useRef } from "react";
import { supabase } from "@/lib/supabase";
import { Send, Search, MoreVertical, Paperclip, Hash, User, Ban, Users, X, Check, FileText, Loader2, Image as ImageIcon, Download, Pin, PinOff } from "lucide-react";
import { toggleChatBan, getGroupMembers, uploadChatAttachment, addMemberToGroup, removeMemberFromGroup, getAllStudents, deleteMessageAdmin, clearGroupChatAdmin } from "@/actions/chat";
import { uploadFiles } from "@/utils/uploadthing";

const getHashStr = (str: string) => {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0; 
  }
  return Math.abs(hash).toString().substring(0, 8);
};

const parseMessageContent = (content: string) => {
  if (!content) return { type: 'text', url: null, text: '', filename: '' };
  if (content.startsWith("[ATTACHMENT:IMAGE]")) {
    const parts = content.split("|");
    const url = parts[0].replace("[ATTACHMENT:IMAGE]", "");
    const text = parts.slice(1).join("|");
    return { type: 'image', url, text, filename: `${getHashStr(url)}.jpg` };
  } else if (content.startsWith("[ATTACHMENT:PDF]")) {
    const parts = content.split("|");
    const url = parts[0].replace("[ATTACHMENT:PDF]", "");
    const text = parts.slice(1).join("|");
    return { type: 'pdf', url, text, filename: `${getHashStr(url)}.pdf` };
  }
  return { type: 'text', url: null, text: content, filename: '' };
};

const handleDownloadFile = async (url: string | null, filename?: string) => {
  if (!url) return;
  try {
    if (url.includes('cloudinary.com')) {
      const baseName = filename ? filename.split('.')[0] : 'mishra_classes_attachment';
      const downloadUrl = url.replace('/upload/', `/upload/fl_attachment:${baseName}/`);
      const a = document.createElement('a');
      a.href = downloadUrl;
      // download attribute might be ignored if cross-origin, but fl_attachment handles it
      a.download = filename || 'mishra_classes_attachment.jpg'; 
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      return;
    }

    // Fallback for Uploadthing PDFs or other sources
    const response = await fetch(url);
    const blob = await response.blob();
    const blobUrl = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = filename || url.split('/').pop() || 'download';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(blobUrl);
  } catch (err) {
    console.error("Download failed:", err);
    window.open(url, '_blank'); // fallback
  }
};

