  const [activeTab, setActiveTab] = useState<'members' | 'add'>('members');

  const [showAttachMenu, setShowAttachMenu] = useState(false);
  const [acceptType, setAcceptType] = useState("image/*,application/pdf");
  const attachMenuRef = useRef<HTMLDivElement>(null);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [pinnedChats, setPinnedChats] = useState<string[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedPinned = localStorage.getItem('pinnedChats_admin');
    if (savedPinned) {
      try { setPinnedChats(JSON.parse(savedPinned)); } catch(e) {}
    }
  }, []);

  const togglePinChat = () => {
    if (!activeGroupId) return;
    setPinnedChats(prev => {
      const newPinned = prev.includes(activeGroupId) ? prev.filter(id => id !== activeGroupId) : [...prev, activeGroupId];
      localStorage.setItem('pinnedChats_admin', JSON.stringify(newPinned));
      return newPinned;
    });
    setShowMenu(false);
  };

  const ADMIN_USER_ID = "00000000-0000-0000-0000-000000000000"; 

  useEffect(() => {
    fetchGroups();

    const handleUnreadUpdate = () => {
      try {
        const counts = JSON.parse(localStorage.getItem('admin_unread_counts') || '{}');
        setGroups(prev => prev.map(g => ({
          ...g,
          unread_count: counts[g.id] || 0
        })));
      } catch(e) {}
    };
    window.addEventListener('admin_unread_updated', handleUnreadUpdate);
    return () => window.removeEventListener('admin_unread_updated', handleUnreadUpdate);
  }, []);



  useEffect(() => {
    if (activeGroupId) {
      setMessages([]);
      fetchMessages(activeGroupId);

      const channel = supabase
        .channel(`room:${activeGroupId}`)
        .on('postgres_changes', { 
          event: 'INSERT', 
          schema: 'public', 
          table: 'messages',
          filter: `group_id=eq.${activeGroupId}` 
        }, async payload => {
          // Fetch just the new message with joins to avoid re-fetching the entire chat history
          const { data: newMsg } = await supabase
            .from('messages')
            .select('*, users(*), reply_to:messages(id, content, sender_id, users(*))')
            .eq('id', payload.new.id)
            .single();

          if (newMsg) {
            setMessages(prev => {
              // Deduplicate optimistic UI messages
              const exists = prev.some(m => m.id === newMsg.id || (m.content === newMsg.content && m.sender_id === newMsg.sender_id && m.id.toString().startsWith('temp-')));
              if (exists) {
                return prev.map(m => (m.id === newMsg.id || (m.content === newMsg.content && m.sender_id === newMsg.sender_id && m.id.toString().startsWith('temp-'))) ? newMsg : m);
              }
              return [...prev, newMsg];
            });
          }
        })
        .on('postgres_changes', {
          event: 'DELETE',
          schema: 'public',
          table: 'messages',
          filter: `group_id=eq.${activeGroupId}`
        }, payload => {
          setMessages(prev => prev.filter(m => m.id !== payload.old.id));
        })
        .subscribe();

      const groupChannel = supabase
        .channel(`group_updates_${activeGroupId}`)
        .on('postgres_changes', {
          event: 'UPDATE',
          schema: 'public',
          table: 'chat_groups',
          filter: `id=eq.${activeGroupId}`
        }, payload => {
          setGroups(prevGroups => prevGroups.map(g => 
            g.id === activeGroupId ? { ...g, ...payload.new } : g
          ));
        })
        .subscribe();

      // Global channel to listen for new messages to update last_message_content
      const globalChannel = supabase
        .channel(`global_messages_${ADMIN_USER_ID}_chats_page`)
        .on('postgres_changes', {
          event: 'INSERT',
          schema: 'public',
          table: 'messages'
        }, payload => {
          if (payload.new.group_id !== activeGroupId && payload.new.sender_id !== ADMIN_USER_ID) {
            setGroups(prevGroups => {
              const newGroups = [...prevGroups];
              const gIdx = newGroups.findIndex(g => g.id === payload.new.group_id);
              if (gIdx >= 0) {
                newGroups[gIdx] = { 
                  ...newGroups[gIdx],
                  last_message_content: payload.new.content,
                  last_message_time: payload.new.created_at
                };
                // Move to top
                const [g] = newGroups.splice(gIdx, 1);
                newGroups.unshift(g);
              }
              return newGroups;
            });
          }
        })
        .subscribe();

      // Local state reset when selecting chat
      setGroups(prevGroups => {
        return prevGroups.map(g => g.id === activeGroupId ? { ...g, unread_count: 0 } : g);
      });

      return () => {
        supabase.removeChannel(channel);
        supabase.removeChannel(groupChannel);
        supabase.removeChannel(globalChannel);
      };
    }
  }, [activeGroupId, ADMIN_USER_ID]);

  useEffect(() => {
