              <div className="space-y-4">
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">Enrolled On</p>
                  <p className="font-semibold text-slate-800 bg-slate-50 px-3 py-2 rounded-lg border border-slate-100 flex items-center gap-2">
                    <Calendar size={14} className="text-indigo-500"/> {enrollmentDate}
                  </p>
                </div>

                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">Valid Till</p>
                  <p className="font-semibold text-slate-800 bg-slate-50 px-3 py-2 rounded-lg border border-slate-100 flex items-center gap-2">
                    <Lock size={14} className="text-emerald-500"/> {validTillDate}
                  </p>
                </div>

                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">Amount Paid</p>
                  <p className="font-black text-indigo-700 bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100 text-lg">
                    ₹{purchase.amount_paid ?? course.price}
                  </p>
                </div>
              </div>

              <div className="mt-6 pt-6 border-t border-slate-100">
                <button 
                  onClick={handleDownloadInvoice} 
                  className="w-full bg-slate-900 hover:bg-slate-800 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-md hover:shadow-lg text-sm"
                >
                  <Download size={16} /> Download Invoice
                </button>
              </div>
            </div>

          </div>
        </aside>

      </div>

      {/* SECURE VOD MODAL */}
      {activeVideoUrl && (
        <div className="fixed inset-0 z-[99999] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 lg:p-12 animate-in fade-in duration-300">
          <div 
            ref={playerContainerRef}
            className={`bg-black overflow-hidden flex flex-col relative animate-in zoom-in-95 duration-300 ${isFullscreen ? 'w-full h-full rounded-none' : 'w-full max-w-5xl aspect-video rounded-3xl border border-white/20 shadow-2xl'}`}
          >
            {/* Header / Controls */}
            <div className="absolute top-0 inset-x-0 h-16 bg-gradient-to-b from-black/80 to-transparent z-50 flex justify-between items-start p-4 pointer-events-none">
              <div className="pointer-events-auto bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10 flex items-center gap-2">
                <Film size={14} className="text-rose-500" />
                <span className="text-white text-xs font-bold tracking-wider uppercase">Recorded Session</span>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={toggleFullscreen}
                  className="pointer-events-auto w-10 h-10 rounded-full bg-black/40 backdrop-blur-md border border-white/10 hover:bg-rose-600 text-white flex items-center justify-center transition-all shadow-lg"
                >
                  {isFullscreen ? <Minimize size={18} /> : <Maximize size={18} />}
                </button>
                <button 
                  onClick={() => {
                    if (document.fullscreenElement) document.exitFullscreen();
                    setActiveVideoUrl(null);
                  }}
                  className="pointer-events-auto w-10 h-10 rounded-full bg-black/40 backdrop-blur-md border border-white/10 hover:bg-rose-600 text-white flex items-center justify-center transition-all shadow-lg"
                >
                  <X size={18} />
                </button>
              </div>
            </div>

            {/* Player Container */}
            <div className="flex-1 relative bg-black overflow-hidden select-none" onContextMenu={(e) => e.preventDefault()}>
              <LivePlayer 
                videoId={
                  (() => {
                    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
                    const match = activeVideoUrl.match(regExp);
                    return (match && match[2].length === 11) ? match[2] : activeVideoUrl;
                  })()
                } 
                controls={true} 
              />

              {/* FLOATING WATERMARK */}
              {studentProfile && (
                <div 
                  className={`absolute text-white font-black uppercase tracking-widest whitespace-nowrap pointer-events-none z-50 mix-blend-difference drop-shadow-md transition-opacity duration-1000 ${watermark.show ? 'opacity-30' : 'opacity-0'}`}
                  style={{
                    top: watermark.top,
                    left: watermark.left,
                  }}
                >
                  <span className="text-[11px] md:text-xs">{studentProfile.full_name}</span> <br/>
                  <span className="text-[9px] md:text-[10px] opacity-80">{studentProfile.phone}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { getRecordedClassesForCourse } from "@/actions/liveClasses";
import { PlayCircle, Clock, Calendar, ArrowLeft, Video } from "lucide-react";
import Link from "next/link";
import { motion } from "framer-motion";

export default function CourseRecordingsPage() {
  const { courseId } = useParams();
  const router = useRouter();
  const [recordings, setRecordings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadRecordings() {
      try {
        const data = await getRecordedClassesForCourse(courseId as string);
        setRecordings(data || []);
      } catch (err) {
        console.error("Failed to fetch recordings", err);
      } finally {
        setLoading(false);
      }
    }
    loadRecordings();
  }, [courseId]);

  return (
    <div className="min-h-screen bg-slate-50 p-6 lg:p-10 font-sans">
      <div className="max-w-7xl mx-auto">

        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button 
            onClick={() => router.back()}
            className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-500 hover:text-indigo-600 hover:border-indigo-200 transition-all shadow-sm"
          >
            <ArrowLeft size={20} />
          </button>
          <div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
              <Video className="text-indigo-600" size={28} />
              Class Recordings
            </h1>
            <p className="text-slate-500 font-medium mt-1">Watch past live sessions at your own pace.</p>
          </div>
        </div>

        {/* Content */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3, 4, 5, 6].map(i => (
              <div key={i} className="animate-pulse bg-white border border-slate-200 rounded-[1.5rem] p-4 h-72">
                <div className="w-full h-40 bg-slate-100 rounded-xl mb-4"></div>
                <div className="h-6 bg-slate-100 rounded-md w-3/4 mb-3"></div>
                <div className="h-4 bg-slate-100 rounded-md w-1/2"></div>
              </div>
            ))}
          </div>
        ) : recordings.length === 0 ? (
          <div className="bg-white border border-slate-200 rounded-[2rem] p-16 flex flex-col items-center justify-center text-center shadow-sm">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mb-6">
              <PlayCircle size={40} className="text-indigo-300" />
            </div>
            <h2 className="text-2xl font-black text-slate-900 mb-2">No Recordings Yet</h2>
            <p className="text-slate-500 font-medium max-w-md">Once live classes are completed and processed, their recordings will automatically appear here.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {recordings.map((rec, idx) => (
              <Link key={rec.id} href={`/student/live-class/${rec.id}`}>
                <motion.div 
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className="group bg-white border border-slate-200 rounded-[1.5rem] overflow-hidden hover:shadow-xl hover:border-indigo-200 transition-all cursor-pointer h-full flex flex-col"
                >
                  {/* Thumbnail Area */}
                  <div className="relative aspect-video w-full overflow-hidden bg-slate-100">
                    {rec.meeting_link ? (
                      <img 
                        src={`https://img.youtube.com/vi/${rec.meeting_link}/maxresdefault.jpg`} 
                        alt={rec.topic}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        onError={(e) => {
                          // Fallback to hqdefault if maxres doesn't exist
                          (e.target as HTMLImageElement).src = `https://img.youtube.com/vi/${rec.meeting_link}/hqdefault.jpg`;
                        }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Video size={40} className="text-slate-300" />
                      </div>
                    )}

                    {/* Play Overlay */}
                    <div className="absolute inset-0 bg-black/20 group-hover:bg-black/40 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                      <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center">
                        <PlayCircle size={32} className="text-white ml-1" />
                      </div>
                    </div>

                    {/* Duration Badge */}
                    <div className="absolute bottom-3 right-3 bg-black/80 backdrop-blur-sm text-white font-mono text-[11px] px-2 py-1 rounded-md tracking-wider flex items-center gap-1.5 shadow-lg">
                      <Clock size={12} className="text-slate-300" />
                      {rec.duration || "00:00:00"}
                    </div>
                  </div>

                  {/* Info Area */}
                  <div className="p-5 flex-1 flex flex-col">
                    <h3 className="text-lg font-black text-slate-900 leading-tight mb-3 line-clamp-2 group-hover:text-indigo-600 transition-colors">
                      {rec.topic}
                    </h3>

                    <div className="mt-auto flex items-center justify-between text-slate-500 text-sm font-medium">
                      <div className="flex items-center gap-1.5">
                        <Calendar size={14} className="text-indigo-400" />
                        {rec.start_time ? new Date(rec.start_time).toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' }) : 'Unknown Date'}
                      </div>
                      <span className="text-[10px] font-black uppercase tracking-widest bg-slate-100 px-2 py-1 rounded text-slate-600">VOD</span>
                    </div>
                  </div>
                </motion.div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

