  useEffect(() => {
    async function loadData() {
      const match = document.cookie.match(/(^| )user_id=([^;]+)/);
      const userId = match ? match[2] : null;

      const [itemsData, coursesData, enrolledData] = await Promise.all([
        getStoreItems(),
        getCourses(),
